/* relative - shifts from its own position */
.relative-box {
  position: relative;
  top: 10px;
  left: 20px;
}

/* absolute - positioned relative to nearest positioned parent */
.parent {
  position: relative;
}
.absolute-box {
  position: absolute;
  top: 0;
  right: 0;
}

/* fixed - stays fixed on scroll */
.fixed-box {
  position: fixed;
  bottom: 10px;
  right: 10px;
}

/* sticky - sticks after scrolling past top: 0 */
.sticky-box {
  position: sticky;
  top: 0;
}

.box1 {
  position: absolute;
  z-index: 1;
}
.box2 {
  position: absolute;
  z-index: 2;   /* box2 appears above box1 */
}

/* Creating a new stacking context */
.parent {
  position: relative;
  z-index: 1;   /* creates a stacking context */
}
.child {
  position: absolute;
  z-index: 9999;  /* still limited within .parent's stacking context */
}

/* static - top/left has no effect */
.static-box {
  position: static;
  top: 20px;  /* ignored */
}

/* relative - top/left shifts it from its normal position */
.relative-box {
  position: relative;
  top: 20px;
  left: 10px;
}

nav {
  position: sticky;
  top: 0;
  background: white;
  z-index: 10;
}

/* nav stays at top: 0 once you scroll to it,
   and scrolls away once its parent container ends */

/* .parent creates a new stacking context because of position + z-index */
.parent {
  position: relative;
  z-index: 1;
}

/* .child z-index only matters within .parent's stacking context */
.child {
  position: absolute;
  z-index: 999;
}

/* .sibling is outside .parent, so it compares stacking
   at the same level as .parent, not .child */
.sibling {
  position: relative;
  z-index: 2;  /* can appear above .parent even though .child has z-index: 999 */
}
